styles:
/* кнопка языка — в верхней строке справа, рядом с дискетой, в её размер */
#toolbar > .langTools {
  flex: none;
  align-self: stretch;
  display: flex;
  align-items: center;
  padding: 3px;
}
.langTools > .toolMenu > summary {
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 32px;
  padding: 4px 7px;
  border: 1px solid #415563;
  border-radius: 7px;
  background: #21313e;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  list-style: none;
  cursor: pointer;
}
.langTools > .toolMenu > summary::-webkit-details-marker {
  display: none;
}
.langTools > .toolMenu > summary::marker {
  content: '';
}
.langTools > .toolMenu[open] > summary,
.langTools > .toolMenu > summary:hover {
  background: var(--hover);
}
/* список языков — столбиком; окну портал сам ставит display:block, поэтому
   раскладка — на кнопках, а не flex на контейнере */
.langList button {
  display: block;
  width: 100%;
  margin: 0 0 4px;
  text-align: left;
}
.langList button:last-child {
  margin-bottom: 0;
}

