styles:
/* Строка «Сечение» (раньше — style.cssText в коде модуля) */
#sectionRow {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  align-items: center;
  width: 100%;
}
.sectionInline .sectionPositionRow {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}
.sectionInline .sectionPositionRow .sectionSlider {
  min-width: 0;
}
.sectionInline .sectionPositionRow #sectionPosition {
  min-width: 0;
  width: var(--compact-slider);
  flex: none;
}
/* Окно «⋯» выводит services.portalToolMenu в общий слой под строкой сечения;
   внутри него — класс .sectionMore (строки .sectionInline над ним уже нет). */
.sectionInline .sectionSlider {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  min-width: 0;
}
.sectionInline #sectionPosition {
  display: inline-block;
  width: var(--compact-slider);
  flex: none;
  min-width: 0;
  margin: 0;
}
.sectionInline #sectionCoordinate,
.sectionMore #sectionCoordinate {
  width: 85px;
  height: 30px;
}
.sectionInline #sectionAxis,
.sectionMore #sectionAxis {
  max-width: 150px;
  height: 30px;
}
.sectionInline .check,
.sectionMore .check {
  white-space: nowrap;
}
.sectionInline .sectionHelp {
  font-size: 12px;
}
.sectionInline .sectionHelp > div {
  margin-top: 4px;
}
#sectionPanel[hidden] {
  display: none;
}
#sectionPanel {
  border-left: 1px solid #33454f;
  padding-left: 10px;
}
#sectionCoordinate {
  width: 120px;
  height: 34px;
  padding: 4px 8px;
  box-sizing: border-box;
  color: #eaf7f3;
  background: #263c47;
  border: 1px solid #526976;
  border-radius: 5px;
}
#sectionTools .toolPopup {
  position: fixed;
  left: 50%;
  top: 76px;
  transform: translateX(-50%);
  width: 440px;
  max-width: calc(100vw - 32px);
  box-sizing: border-box;
  max-height: 70vh;
  overflow: auto;
}
#sectionTools .sectionSlider {
  display: block;
  width: 100%;
}
#sectionPosition {
  display: block;
  width: 100%;
  min-width: 0;
  margin: 20px 0;
}
#sectionTools .tools {
  flex-wrap: wrap;
}
#sectionTools .check {
  justify-content: space-between;
}
@media (max-width: 760px) {
  .sectionInline .sectionDirection > span {
    display: none;
  }
  .sectionInline {
    column-gap: 6px !important;
  }
  .sectionInline .toolMenu > summary {
    padding: 4px;
  }
  .sectionInline .sectionPositionRow {
    flex-wrap: wrap;
  }
  .sectionInline .sectionPositionRow #sectionPosition {
    width: var(--compact-slider);
  }
}
/* В панели инструмента (ПК) и листе (телефон) — правило оболочки: один элемент —
   одна строка (toolbar, .toolStack; владелец 24.10.2026). Строчная раскладка выше
   остаётся для строки вне панели. */
.toolPanelBody #sectionRow,
.toolPanelBody #sectionRow .sectionPositionRow {
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 8px;
}
.toolPanelBody #sectionRow .sectionPositionRow {
  flex: none;
}
.toolPanelBody #sectionRow .sectionDirection > span {
  display: none; /* подпись — первой строкой списка выбора */
}
.toolPanelBody #sectionRow #sectionAxis {
  flex: 1 1 auto;
  width: 100%;
  max-width: none;
  height: auto;
}
.toolPanelBody #sectionRow .sectionSlider {
  flex: none;
}
.toolPanelBody #sectionRow #sectionPosition {
  flex: 1 1 auto;
  width: auto;
  min-width: 120px;
}

