styles:
/* список сохранённых сечений */
.sectionViewsPopup {
  min-width: 300px;
  max-width: 380px;
}
.sectionViewsList {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 55vh;
  overflow: auto;
  margin-bottom: 6px;
}
.sectionViewRow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 4px;
  border: 1px solid transparent;
  border-radius: 5px;
}
.sectionViewRow.on {
  border-color: #e53935;
  background: #e5393518;
}
.sectionViewRow img {
  width: 72px;
  height: 46px;
  object-fit: cover;
  border-radius: 3px;
  background: #0b1217;
  flex: none;
}
.sectionViewRow input[type='text'] {
  width: 56px;
  flex: none;
  font-weight: 700;
  text-align: center;
}
.sectionViewRow .sectionViewMeta {
  flex: 1;
  min-width: 0;
  font-size: 11px;
  color: var(--muted-soft, #9aa9b1);
}
.sectionViewRow button.sectionViewUpdate,
.sectionViewRow button.sectionViewDelete {
  flex: none;
  padding: 2px 6px;
}
.sectionViewsHint {
  display: block;
  color: var(--muted-soft, #9aa9b1);
  max-width: 340px;
}
/* обозначения на модели: номер у концов линии сечения */
.sectionMarkLabels {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
}
.sectionMarkLabel {
  position: absolute;
  transform: translate(-50%, -50%);
  min-width: 18px;
  padding: 0 4px;
  border-radius: 3px;
  background: #b71c1cee;
  color: #fff;
  font: 700 13px/18px system-ui;
  text-align: center;
  pointer-events: auto;
  cursor: pointer;
}
.sectionMarkLabel.on {
  background: #e53935;
  box-shadow: 0 0 0 2px #fff8;
}
.sectionViewRow button.sectionViewUpdate[hidden] {
  display: none;
}
.sectionViewRow button.sectionViewUpdate.dirty {
  border-color: #f1c232;
  color: #f1c232;
}

