styles:
.matList {
  max-height: 62vh;
  overflow: auto;
  min-width: 230px;
}
.matRow {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 3px;
  border-top: 1px solid var(--divider);
}
.matRow:first-child {
  border-top: 0;
}
.matHead {
  display: flex;
  align-items: center;
  gap: 9px;
}
.matThumb {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1px solid var(--control-border);
  background-size: cover;
  background-position: center;
  flex: none;
}
.matName {
  font-size: 12.5px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}
.matTools {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-left: 39px;
}
.matTools > * {
  flex: none;
}
.matTools button {
  width: 31px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  padding: 0;
  border: 1px solid var(--control-border);
  background: #1d2b34;
  border-radius: 6px;
  cursor: pointer;
  color: var(--text);
}
.matGlass {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 39px;
  font-size: 12px;
  color: var(--muted);
}
.matGlass .range {
  flex: 1;
  min-width: 70px;
  margin: 0;
}
.matGlass output {
  width: 38px;
  text-align: right;
  color: var(--text);
}
.matTools input[type='color'] {
  width: 31px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--control-border);
  border-radius: 6px;
  background: none;
  cursor: pointer;
}
.matPicker {
  position: fixed;
  z-index: 90;
  max-height: 52vh;
  overflow: auto;
  min-width: 210px;
  padding: 4px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.matPicker button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--text);
  padding: 6px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
}
.matPicker button:hover,
.matPicker button:focus-visible {
  background: var(--hover);
}
.matPicker .pk {
  width: 22px;
  height: 22px;
  border-radius: 4px;
  border: 1px solid var(--control-border);
  background: #0003;
  background-size: cover;
  background-position: center;
  flex: none;
}

/* Раньше — встроенные стили в коде модуля. Селекторы сильнее прежних правил
   (.matPicker), потому что встроенный стиль их перебивал — так и осталось. */
#matEditor {
  width: 520px;
  max-width: calc(100vw - 24px);
  max-height: 85vh;
  overflow: auto;
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--popup-border);
  border-radius: 10px;
  padding: 14px;
}
#matEditor .matEditorHead {
  justify-content: space-between;
}
input.matFile {
  display: block;
  max-width: 100%;
  margin: 8px 0;
}
.matMono {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding-left: 39px;
  font-size: 11px;
}
.matMono .matMonoChip {
  display: inline-block;
  width: 20px;
  height: 20px;
  border: 1px solid #8ca1aa;
  border-radius: 4px;
}
dialog.matPicker {
  width: 360px;
  max-width: calc(100vw - 24px);
  max-height: 75vh;
  color: var(--text);
}
/* инструменты правки в выноске материала (кнопка «Редактор материалов» на ПК) */
.matCalloutTools button {
  min-width: 24px;
  padding: 1px 5px;
  font-size: 12px;
  line-height: 18px;
}
.matCalloutTools .matCalloutGlass {
  width: 70px;
}
.matCalloutTools output {
  font-size: 11px;
  color: var(--muted-soft, #9aa9b1);
}

/* телефон: «Редактор материалов» и так открывает окно со всеми материалами.
   !important и #layerTools — значки (icon_controls) ставят кнопкам display с
   !important, и в режиме значков «Все материалы» на телефоне снова появлялась
   второй «☰» (проба на S24). */
@media (max-width: 760px) {
  #matEditorList,
  html.iconControls #layerTools #matEditorList {
    display: none !important;
  }
