styles:
.noteCallouts {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 4;
}
.noteCallout {
  position: absolute;
  display: none;
  box-sizing: border-box;
  padding: 5px 7px;
  background: #2b2616ee;
  border: 1px solid #9c8545;
  border-left: 4px solid #e2b93b;
  border-radius: 5px;
  color: #fbf5e3;
  font: 12px/16px system-ui;
  pointer-events: auto;
  cursor: pointer;
}
.noteCallout .noteText {
  display: block;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: 96px;
  overflow: hidden;
}
.noteCallout .noteText[hidden] {
  display: none;
}
.noteCallout small {
  display: block;
  margin-top: 2px;
  color: #d9c89a;
  overflow-wrap: anywhere;
}
.noteCallout:hover,
.noteCallout.focus {
  border-color: #ffd970;
  background: #3a3219f4;
}
.noteCallout.occluded {
  opacity: 0.62;
}
.noteLeader {
  position: absolute;
  display: none;
  height: 0;
  border-top: 1px solid #e2b93b;
  transform-origin: 0 0;
  pointer-events: none;
}
.noteLeader.occluded {
  border-top-style: dashed;
  opacity: 0.7;
}
.noteDot {
  position: absolute;
  display: none;
  width: 8px;
  height: 8px;
  margin: -4px 0 0 -4px;
  border-radius: 50%;
  background: #e2b93b;
  box-shadow: 0 0 0 2px #2b2616;
  pointer-events: none;
}
.noteDot.occluded {
  opacity: 0.5;
}
#viewport.measuring .noteCallout {
  pointer-events: none;
}
.noteStatus {
  font-size: 11px;
  color: var(--muted-soft);
  max-width: 340px;
}
.noteList {
  min-width: 250px;
  max-height: 58vh;
  overflow: auto;
}
.noteItem {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 2px;
  border-top: 1px solid var(--divider);
}
.noteItem:first-child {
  border-top: 0;
}
.noteItem .noteGo {
  flex: 1;
  min-width: 0;
  text-align: left;
  background: none;
  border: 0;
  color: inherit;
  padding: 2px;
  cursor: pointer;
  font-size: 12px;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.noteItem .noteGo small {
  display: block;
  color: var(--muted-soft);
}
.noteItem button.noteIcon {
  flex: none;
  width: 28px;
  height: 26px;
  padding: 0;
  display: inline-grid;
  place-items: center;
}
.noteItem button.noteIcon svg {
  width: 16px;
  height: 16px;
}
.noteItem.noteOff .noteGo {
  opacity: 0.5;
}
.noteMenu {
  position: fixed;
  z-index: 85;
  min-width: 190px;
  padding: 5px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.noteMenu[hidden] {
  display: none;
}
.noteMenu button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 6px 8px;
  border-radius: 5px;
  cursor: pointer;
}
.noteMenu button:hover,
.noteMenu button:focus-visible {
  background: var(--hover);
}
.noteEmpty {
  font-size: 12px;
  color: var(--muted-soft);
  padding: 4px;
}
.noteEditor,
.noteChat {
  /* плавающее окно: место задаёт модуль (left/top), тащится за заголовок */
  position: fixed;
  inset: auto;
  margin: 0;
  z-index: 40;
  max-height: calc(100vh - 16px);
  overflow: auto;
  box-shadow: 0 12px 35px #0008;
  width: 440px;
  max-width: calc(100vw - 24px);
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--popup-border);
  border-radius: 10px;
  padding: 14px;
}
.noteEditorHead {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: -14px -14px 6px;
  padding: 10px 14px 6px;
  cursor: grab;
  user-select: none;
  touch-action: none;
}
.noteEditorHead:active {
  cursor: grabbing;
}
.noteEditorGrip {
  color: var(--muted-soft);
  font-size: 14px;
  line-height: 1;
}
.noteEditor::backdrop {
  background: #0006;
}
.noteEditor small {
  display: block;
  color: var(--muted-soft);
  margin: 2px 0 8px;
  overflow-wrap: anywhere;
}
.noteEditor textarea,
.noteChat textarea {
  display: block;
  width: 100%;
  min-height: 110px;
  box-sizing: border-box;
  resize: vertical;
  background: #0f1a21;
  color: var(--text);
  border: 1px solid var(--control-border);
  border-radius: 6px;
  padding: 8px;
  font: 13px/1.4 system-ui;
}
.noteEditor .noteButtons,
.noteChat .noteButtons {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 10px;
}
.noteEditor .noteButtons .noteDelete,
.noteChat .noteChatEditButton {
  margin-right: auto;
}

.notesToolItems {
  display: contents;
}

/* несколько мест: флажок и кнопки в редакторе, плашка выбора мест */
.notePlacesRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin-top: 8px;
}
.notePlaces {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.notePlaces[hidden] {
  display: none;
}
.noteEditor .notePlaces small {
  margin: 0;
}
.notePickBar {
  white-space: normal;
  max-width: calc(100% - 16px);
}

/* Сечение «окном»: флажок и настройки плоскости и рамки в редакторе */
.noteWindowRow {
  margin-top: 8px;
}
.noteWindowBox {
  display: grid;
  gap: 6px;
  margin: 6px 0 0 22px;
}
.noteWindowBox[hidden] {
  display: none;
}
.noteWindowLine {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
}
.noteWindowLine > span:first-child {
  min-width: 74px;
}
.noteWindowLine input[type='number'] {
  width: 68px;
}
.noteWindowLine .range {
  flex: 1 1 120px;
}
.noteWindowMode[aria-pressed='true'],
.noteWindowAxis[aria-pressed='true'] {
  background: #315e5d;
  border-color: var(--accent);
}
/* «Скрыть остальные»: флажок и пояснение в редакторе */
.noteIsolateRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px 12px;
  margin-top: 8px;
}
.noteEditor .noteIsolateRow small {
  flex-basis: 100%;
}
/* узел (сфера): флажок и диаметр в редакторе */
.noteSphereRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin-top: 8px;
}
.noteSphereSize {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 200px;
  font-size: 12px;
  color: var(--muted-soft);
}
.noteSphereSize[hidden] {
  display: none;
}
.noteSphereSize .range {
  flex: 1;
  min-width: 80px;
  margin: 0;
}
.noteSphereSize output {
  min-width: 64px;
  text-align: right;
  color: var(--text);
}

/* ракурс заметки: строка в редакторе, плашка «внутри заметки», метка на карточке */
.noteViewRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.noteViewRow button {
  flex: none;
  white-space: nowrap;
}
.noteEditor .noteViewRow small {
  flex: 1 1 160px;
  margin: 0;
  font-size: 11px;
}
.noteViewBar {
  position: absolute;
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 7;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 4px 4px 12px;
  background: #514423f0;
  color: #ffe49a;
  border: 1px solid #e2b93b;
  border-radius: 8px;
  font-size: 12px;
  white-space: nowrap;
}
.noteViewBar[hidden] {
  display: none;
}
.noteViewBar button {
  padding: 4px 10px;
  font-size: 12px;
}
/* Значок «нажми» у заметок, по которым нажимают (ракурс, узел): палец с
   волнами. Маска — цвет берётся из background-color, как у значков кнопок. */
.noteCallout.noteHasView .noteText::before {
  content: '';
  display: inline-block;
  width: 15px;
  height: 15px;
  margin-right: 5px;
  vertical-align: -3px;
  background-color: #e2b93b;
  -webkit-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%221.8%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M4.5%209.5a7.5%207.5%200%200%201%2015%200%22/%3E%3Cpath%20d%3D%22M7.8%209.5a4.2%204.2%200%200%201%208.4%200%22/%3E%3Cpath%20d%3D%22M10.6%2021.5v-3.2L8%2015.4a1.4%201.4%200%200%201%202.1-1.9l.9.9V9.6a1.4%201.4%200%200%201%202.8%200v4.2a1.4%201.4%200%200%201%202.7.5%201.4%201.4%200%200%201%202.6.8V18a3.5%203.5%200%200%201-3.5%203.5z%22/%3E%3C/svg%3E") center / contain no-repeat;
  mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%221.8%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M4.5%209.5a7.5%207.5%200%200%201%2015%200%22/%3E%3Cpath%20d%3D%22M7.8%209.5a4.2%204.2%200%200%201%208.4%200%22/%3E%3Cpath%20d%3D%22M10.6%2021.5v-3.2L8%2015.4a1.4%201.4%200%200%201%202.1-1.9l.9.9V9.6a1.4%201.4%200%200%201%202.8%200v4.2a1.4%201.4%200%200%201%202.7.5%201.4%201.4%200%200%201%202.6.8V18a3.5%203.5%200%200%201-3.5%203.5z%22/%3E%3C/svg%3E") center / contain no-repeat;
}
.noteCallout.noteActive {
  outline: 2px solid #e2b93b;
  outline-offset: 1px;
}
/* Узел (местный разрез сферой) — бирюзовый, а не жёлтый, как обычные заметки:
   сразу видно, что по нему нажимают, чтобы посмотреть узел крупным планом. */
/* обрезанный длинный текст — растворяется книзу, под ним «…ещё» */
.noteCallout .noteText.noteClipped {
  -webkit-mask-image: linear-gradient(#000 70%, transparent);
  mask-image: linear-gradient(#000 70%, transparent);
}
.noteCallout .noteMore {
  display: block;
  margin: 0 0 0 auto;
  padding: 0 2px;
  border: 0;
  background: none;
  color: #ffd970;
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}
.noteCallout.noteCollapsed .noteOffer,
.noteCallout.noteCollapsed .noteMore,
.noteCallout .noteMore[hidden],
.noteCallout .noteOffer[hidden] {
  display: none;
}
/* предложение клиента к заметке: что изменил, «Принять / Отклонить» */
.noteCallout.noteHasOffer {
  border-color: #b388ff;
}
.noteCallout .noteOffer {
  margin-top: 4px;
  padding: 4px 6px;
  border-radius: 4px;
  background: #2a1f45ee;
  color: #eadfff;
}
.noteOfferLine {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.noteOfferLine .noteOfferText {
  display: block;
  max-height: 96px;
  overflow: auto;
  color: #fff;
}
.noteOfferConflict {
  margin-top: 3px;
  color: #ffb4a8;
}
.noteOfferConflict::before {
  content: '⚠ ';
}
.noteOfferButtons {
  display: flex;
  gap: 6px;
  margin-top: 5px;
}
.noteOfferButtons button {
  flex: 1;
  padding: 3px 6px;
  border-radius: 4px;
  border: 1px solid #b388ff;
  background: #3b2a63;
  color: #fff;
  font: inherit;
  cursor: pointer;
}
.noteOfferButtons .noteOfferReject {
  background: transparent;
  color: #d9c8ff;
}
/* заметка клиента (принята из правок) — фиолетовая полоса слева */
.noteCallout.noteClient {
  border-left-color: #b388ff;
}
.noteCallout.noteSphere {
  background: #13283aee;
  border-color: #3f8fb0;
  border-left-color: #4fc3f7;
  color: #e6f6fd;
}
.noteCallout.noteSphere small {
  color: #a9d4e6;
}
.noteCallout.noteSphere:hover,
.noteCallout.noteSphere.focus {
  border-color: #8fdcff;
  background: #1a3850f4;
  box-shadow: 0 0 0 2px #4fc3f744;
}
.noteCallout.noteSphere .noteText::before {
  background-color: #4fc3f7;
}
.noteCallout.noteSphere.noteActive {
  outline-color: #4fc3f7;
}
.noteLeader.noteSphere {
  border-top-color: #4fc3f7;
}
.noteDot.noteSphere {
  background: #4fc3f7;
  box-shadow: 0 0 0 2px #13283a;
}

/* фото заметки: миниатюры в редакторе и просмотр в полный размер */
.noteImages {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.noteImages:empty {
  display: none;
}
.noteThumb {
  position: relative;
  width: 72px;
  height: 72px;
  border: 1px solid var(--control-border);
  border-radius: 6px;
  overflow: hidden;
  background: var(--divider);
}
.noteThumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: zoom-in;
  display: block;
}
.noteThumb button {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 22px;
  height: 22px;
  padding: 0;
  border-radius: 50%;
  line-height: 20px;
  background: #17232dd9;
}
.notePhotoRow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.notePhotoRow button {
  flex: none;
  white-space: nowrap;
}
.noteEditor .notePhotoRow small {
  margin: 0;
  font-size: 11px;
}
.noteImageView {
  max-width: calc(100vw - 24px);
  max-height: calc(100vh - 24px);
  padding: 0;
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  background: #0b1318;
}
.noteImageView::backdrop {
  background: #000b;
}
.noteImageView img {
  display: block;
  max-width: calc(100vw - 26px);
  max-height: calc(100vh - 26px);
  cursor: zoom-out;
}
.noteImageView button {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 30px;
  height: 30px;
  padding: 0;
  border-radius: 50%;
  background: #17232dd9;
}
.noteImageView .noteImageNav {
  top: 50%;
  width: 40px;
  height: 40px;
  margin-top: -20px;
  font-size: 26px;
  line-height: 36px;
}
#noteImageViewPrev {
  left: 6px;
  right: auto;
}
#noteImageViewNext {
  right: 6px;
}
.noteImageCount {
  position: absolute;
  left: 50%;
  bottom: 8px;
  transform: translateX(-50%);
  padding: 2px 8px;
  border-radius: 10px;
  background: #17232dd9;
  font-size: 12px;
}

/* пометка «📷 N» и превью первого фото на карточке у модели */
.notePhotoMark {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 5px;
  border-radius: 9px;
  background: #7ddcff26;
  color: #7ddcff;
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
  vertical-align: middle;
}
.notePhotoMark svg {
  width: 13px;
  height: 13px;
}
.noteCallout .noteCardPhotos {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  cursor: zoom-in;
}
.noteCallout .noteCardPhotos[hidden] {
  display: none;
}
.noteCallout .noteCardPhotos img {
  width: 56px;
  height: 42px;
  object-fit: cover;
  border-radius: 4px;
  border: 1px solid #9c8545;
  background: #1c1a12;
}

/* не нажата — только цветная обводка (фон как у всех кнопок), нажата — заливка:
   иначе не понять, включены ли заметки */
#notesOpen,
#notesOpen.viewerIconControl {
  color: #fbf5e3;
  border-color: #c9a646;
}
#notesOpen[aria-pressed='true'],
html.iconControls #notesOpen[aria-pressed='true'] {
  background: #514423;
  color: #ffe49a;
  border-color: #e2b93b;
}
.noteBadge,
.noteMobileEdit {
  display: none;
}
@media (max-width: 760px) {
  /* окно заметки — лист снизу не выше 40 % экрана, содержимое прокручивается
     внутри (владелец после пробы на S24); тащить его на телефоне незачем */
  .noteEditor {
    left: 0 !important;
    right: 0;
    top: auto !important;
    bottom: 0;
    width: 100%;
    max-width: none;
    max-height: 40vh;
    max-height: 40dvh;
    border-bottom: 0;
    border-radius: 20px 20px 0 0;
    overscroll-behavior: contain;
  }
  .noteEditor .noteEditorHead {
    cursor: default;
  }
  .noteCallout.noteSphere .noteBadge {
    color: #8fdcff;
  }
  .noteCallout .noteBadge {
    display: inline-grid;
    place-items: center;
    width: 36px;
    height: 36px;
    padding: 6px;
    border: 0;
    background: transparent;
    color: #ffe49a;
    vertical-align: middle;
  }
  .noteBadge svg {
    width: 24px;
    height: 24px;
  }
  .noteCallout.noteCollapsed {
    height: 42px;
    padding: 2px;
    border-left-width: 1px;
  }
  .noteCallout.noteCollapsed .noteText,
  .noteCallout.noteCollapsed small,
  .noteCallout.noteCollapsed .noteCardPhotos {
    display: none;
  }
  .noteCallout:not(.noteCollapsed) .noteMobileEdit {
    display: inline-block;
    font-size: 11px;
    padding: 4px;
  }
  .noteCallout:not(.noteCollapsed) .noteText {
    max-height: 45vh;
    overflow: auto;
  }
}
/* обсуждение: открытый вопрос — оранжевый, согласованное решение — зелёное */
.noteCallout.noteThread {
  border-color: #c9773a;
  border-left-color: #ff8a3d;
  background: #36220fee;
}
.noteCallout.noteAgreed {
  border-color: #3c9a5a;
  border-left-color: #3fcf6e;
  background: #12301cee;
}
.noteCallout .noteQuestion {
  margin-bottom: 3px;
  color: #ffb37a;
  font-size: 11px;
  line-height: 14px;
  max-height: 28px;
  overflow: hidden;
}
.noteCallout .noteQuestion[hidden],
.noteCallout .noteTalk[hidden] {
  display: none;
}
.noteCallout .noteTalk {
  margin-top: 3px;
  font-size: 11px;
  line-height: 14px;
  color: #ffd2ad;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.noteCallout.noteAgreed .noteTalk {
  color: #9ff0b8;
}
.noteCallout .noteTalk em {
  color: #ffcf6e;
  font-style: normal;
  font-weight: 600;
}
/* окно обсуждения */
.noteChat {
  width: 400px;
}
.noteChatStatus {
  margin-left: auto;
  padding: 1px 8px;
  border-radius: 10px;
  font-size: 11px;
  background: #ff8a3d33;
  color: #ffb37a;
}
.noteChatStatus[data-status='proposed'] {
  background: #3fcf6e22;
  color: #9ff0b8;
}
.noteChatStatus[data-status='agreed'] {
  background: #3fcf6e44;
  color: #c8ffd8;
}
.noteChatList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: min(52vh, 460px);
  overflow: auto;
  margin-bottom: 8px;
}
.noteMsg {
  max-width: 88%;
  padding: 5px 8px;
  border-radius: 8px;
  background: #1b2a33;
  border: 1px solid #2c3f4a;
  font-size: 13px;
}
.noteMsgMine {
  align-self: flex-end;
  background: #1f3340;
}
.noteMsgTheirs {
  align-self: flex-start;
  background: #2a2140;
  border-color: #4a3a72;
}
.noteMsgQuestion {
  border-color: #ff8a3d;
  background: #36220f;
}
.noteMsgProposed {
  border: 1px dashed #3fcf6e;
}
.noteMsgDecision {
  border: 1px solid #3fcf6e;
  background: #12301c;
}
.noteMsgHead {
  font-size: 11px;
  color: var(--muted-soft);
  margin-bottom: 2px;
}
.noteMsgHead b {
  color: var(--text);
}
.noteMsgTag {
  color: #ffb37a;
}
.noteMsgText {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.noteMsgActions {
  margin-top: 4px;
  font-size: 11px;
  color: #9ff0b8;
}
.noteMsgActions button {
  padding: 2px 6px;
  font-size: 11px;
  border-radius: 4px;
}
.noteMsgActions .noteMsgAgree {
  border-color: #3fcf6e;
  background: #1d4a2c;
  color: #fff;
}
.noteMsgEvent {
  align-self: center;
  font-size: 11px;
  color: #9ff0b8;
}
.noteChat textarea {
  min-height: 60px;
}

/* своё сообщение, ещё не принятое хостом: «Изменить» / «Удалить» */
.noteMsgOwnTools {
  display: flex;
  gap: 4px;
  margin-top: 4px;
}
.noteMsgOwnTools button {
  padding: 1px 6px;
  font-size: 11px;
  border-radius: 4px;
}
.noteMsgEditArea {
  width: 100%;
  min-height: 54px;
  box-sizing: border-box;
  font: inherit;
  resize: vertical;
}

