styles:
.visibilityTools {
  display: flex;
  gap: 5px;
}
.visibilityTools button[aria-pressed='true'] {
  background: #35615e;
  border-color: #70c7b9;
}
.visibilityMenu {
  position: fixed;
  z-index: 80;
  min-width: 220px;
  padding: 5px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.visibilityMenu button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
}
.visibilityMenu button:hover,
.visibilityMenu button:focus-visible {
  background: var(--hover);
}
.visibilityHidden {
  opacity: 0.46;
}
.assemblyBadge {
  margin-left: 6px;
  padding: 1px 4px;
  border: 1px solid var(--popup-border);
  border-radius: 4px;
  color: var(--accent);
  font-size: 9px;
  white-space: nowrap;
}

