styles:
/* Кнопки правок клиента — в верхней строке у языка */
.inboxButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.inboxButton[hidden] {
  display: none;
}
.inboxButton svg {
  width: 17px;
  height: 17px;
  flex: none;
}
/* «Загрузить правки» — заметная, как «Обновить» */
.inboxButton.inboxLoad {
  border-color: #b388ff;
  color: #e5d8ff;
}
/* Клиенту дискета и «Принять / Отклонить» не нужны: сохранить на GitHub он не может */
.bazisClient #githubSaveTools,
.bazisClient .noteOfferButtons {
  display: none !important;
}
@media (max-width: 700px) {
  .inboxButton span {
    display: none;
  }
  .inboxButton {
    width: 34px;
    justify-content: center;
    padding: 0;
  }
}
.inboxDialog {
  max-width: 400px;
  width: calc(100vw - 32px);
  box-sizing: border-box;
  border: 1px solid #6c8696;
  border-radius: 8px;
  background: #101a21;
  color: #e9f1f4;
  padding: 16px 18px;
}
.inboxDialog::backdrop {
  background: #03080c99;
}
.inboxDialog h3 {
  margin: 0 0 6px;
}
.inboxDialog p {
  margin: 0 0 8px;
  font-size: 13px;
  line-height: 1.4;
}
.inboxField {
  display: grid;
  gap: 3px;
  margin-bottom: 8px;
  font-size: 13px;
}
.inboxField input,
.inboxField textarea {
  width: 100%;
  box-sizing: border-box;
}
.inboxStatus:empty {
  display: none;
}
.inboxButtons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.inboxPrimary {
  background: #315e5d;
  border-color: var(--accent, #6fe3d3);
}
/* окно просмотра пришедших правок */
.inboxReview {
  max-width: 520px;
}
.inboxReviewList {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: min(60vh, 520px);
  overflow: auto;
  margin-bottom: 8px;
}
.inboxEdit {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 2px 8px;
  padding: 7px 9px;
  border: 1px solid #4a3a72;
  border-radius: 6px;
  background: #1a1430;
}
.inboxEdit > input {
  grid-row: span 3;
  margin-top: 3px;
}
.inboxEditHead {
  font-size: 13px;
}
.inboxEditHead span {
  color: #a9b6bd;
  font-size: 12px;
}
.inboxEditComment {
  font-size: 12px;
  color: #eadfff;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.inboxEditItems {
  margin: 2px 0 0;
  padding-left: 16px;
  font-size: 12px;
}
.inboxEditItems li {
  margin: 1px 0;
  overflow-wrap: anywhere;
}
.inboxEditItems b {
  font-weight: 600;
  color: #ffb37a;
}
.inboxEditItems q {
  color: #fff;
}
.inboxEditItems small {
  display: block;
  color: #8fa2ad;
}
.inboxReject {
  margin-right: auto;
  border-color: #b06a5e;
  color: #ffc4ba;
}

