styles:
/* Text stays in the DOM for translation, tooltips and accessible names. */
html.iconControls :not(.toolRail) > .viewerIconControl:not([hidden]):not(.hidden) {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  font-size: 0 !important;
  line-height: 0 !important;
  gap: 0 !important;
  width: 40px !important;
  min-width: 40px !important;
  max-width: 40px !important;
  height: 40px;
  min-height: 40px;
  padding: 8px !important;
  box-sizing: border-box;
  flex: 0 0 40px !important;
}
html.iconControls :not(.toolRail) > .viewerIconControl::before {
  content: '';
  display: block;
  width: 22px;
  height: 22px;
  flex: none;
  background: currentColor;
  mask: var(--viewer-control-icon) center/contain no-repeat;
  -webkit-mask: var(--viewer-control-icon) center/contain no-repeat;
}
html.iconControls :not(.toolRail) > .viewerIconControl::after,
html.iconControls :not(.toolRail) > .viewerIconControl::-webkit-details-marker {
  display: none !important;
  content: none !important;
}
html.iconControls :not(.toolRail) > .viewerIconControl::marker {
  content: '';
}
html.iconControls :not(.toolRail) > .viewerIconControl > * {
  display: none !important;
}
#visibilityMode.viewerIconControl[aria-pressed='false'] {
  --viewer-control-icon: var(--viewer-assembly-icon) !important;
}
html.iconControls :not(.toolRail) > .viewerIconControl[aria-pressed='true'],
html.iconControls .toolMenu[open] > .viewerIconControl {
  color: #b9fff0;
  border-color: #70c7b9;
  background: #315e5d;
}
@media (max-width: 760px) {
  html.iconControls :not(.toolRail) > .viewerIconControl:not([hidden]):not(.hidden) {
    width: 44px !important;
    min-width: 44px !important;
    max-width: 44px !important;
    height: 44px;
    flex-basis: 44px !important;
    padding: 6px !important;
  }
}

html.iconControls :not(.toolRail) > .viewerColorIcon::before {
  mask: none;
  -webkit-mask: none;
  background: var(--viewer-control-icon) center/contain no-repeat;
}

@media (max-width: 340px) {
  html.iconControls :not(.toolRail) > .viewerIconControl:not([hidden]):not(.hidden) {
    width: 40px !important;
    min-width: 40px !important;
    max-width: 40px !important;
    flex-basis: 40px !important;
  }
}

/* Оболочка RF-013: в меню слева и у кнопок выбора в верхней строке значок есть
   всегда (подпись остаётся рядом или под ним); без этого модуля — только подписи. */
.toolRail > .viewerIconControl::before,
#toolbar #selectionTools .viewerIconControl::before {
  content: '';
  display: block;
  flex: none;
  width: 22px;
  height: 22px;
  background: currentColor;
  mask: var(--viewer-control-icon) center/contain no-repeat;
  -webkit-mask: var(--viewer-control-icon) center/contain no-repeat;
}
#toolbar #selectionTools .viewerIconControl::before {
  width: 18px;
  height: 18px;
}
.toolRail > .viewerColorIcon::before,
#toolbar #selectionTools .viewerColorIcon::before {
  mask: none;
  -webkit-mask: none;
  background: var(--viewer-control-icon) center/contain no-repeat;
}
/* на ПК значок заменяет короткую подпись-символ (↶, ⚙) */
@media (min-width: 761px) {
  #toolbar #selectionTools .viewerIconControl::after {
    content: none !important;
  }
}

/* Панель инструмента (ПК) и лист (телефон): один элемент — одна строка (правило
   toolbar), поэтому значок здесь — рядом с полной подписью, а не вместо неё:
   одинаковые значки у разных действий больше не путают (владелец после пробы на
   S24). В сегменте однотипных (.views, .toolSegment) — значок над подписью. */
html.iconControls .toolPanelBody .viewerIconControl:not([hidden]):not(.hidden) {
  flex-direction: row;
  justify-content: flex-start;
  gap: 10px !important;
  width: 100% !important;
  min-width: 0 !important;
  max-width: none !important;
  flex: none !important;
  height: auto;
  min-height: var(--ui-hit, 44px);
  padding: 0 12px !important;
  font-size: 13px !important;
  line-height: 16px !important;
}
html.iconControls .toolPanelBody :is(.views, .toolSegment) > .viewerIconControl:not([hidden]):not(.hidden) {
  flex-direction: column;
  justify-content: center;
  gap: 3px !important;
  flex: 1 1 0 !important;
  min-height: 56px;
  padding: 6px 2px 4px !important;
  font-size: 11px !important;
  line-height: 13px !important;
  white-space: nowrap;
}
/* у меню-строки («В сносках…», «Настройки») стрелка справа рисуется оболочкой */
html.iconControls .toolPanelBody .toolMenu > .viewerIconControl::after {
  display: block !important;
  content: '›' !important;
  margin-left: auto;
  font-size: 18px;
  color: var(--ui-text-tertiary, #7f97a5);
}

