k","uk":"див. вид"},"т.верх":{"en":"e.top","pl":"kr.góra","uk":"т.верх"},"т.лев":{"en":"e.left","pl":"kr.lewa","uk":"т.лів"},"т.низ":{"en":"e.bottom","pl":"kr.dół","uk":"т.низ"},"т.пр":{"en":"e.right","pl":"kr.prawa","uk":"т.пр"},"толщ.":{"en":"thk.","pl":"grub.","uk":"товщ."},"удалена":{},"— выберите —":{"en":"— choose —","pl":"— wybierz —","uk":"— оберіть —"},"— добавить —":{},"↶ Отменить":{},"↷ Повторить":{},"✕ Закрыть":{"en":"✕ Close","pl":"✕ Zamknij","uk":"✕ Закрити"},"✕ ряд":{"en":"✕ row","pl":"✕ wiersz","uk":"✕ ряд"},"✥ Двигать детали":{},"✥ Двигать детали — вкл.":{},"＋ Взрыв-схема":{},"＋ Вид":{"en":"＋ View","pl":"＋ Widok","uk":"＋ Вид"},"＋ Выноска":{"en":"＋ Callout","pl":"＋ Odnośnik","uk":"＋ Виноска"},"＋ Детали":{"en":"＋ Parts","pl":"＋ Elementy","uk":"＋ Деталі"},"＋ Зона":{},"＋ Лист":{"en":"＋ Sheet","pl":"＋ Arkusz","uk":"＋ Аркуш"},"＋ Между деталями":{},"＋ Новый лист после этого":{},"＋ Погонаж":{"en":"＋ Linear","pl":"＋ Liniowe","uk":"＋ Погонаж"},"＋ Размер":{"en":"＋ Dimension","pl":"＋ Wymiar","uk":"＋ Розмір"},"＋ Размер блока":{},"＋ Размер детали":{},"＋ Рамка изделия":{"en":"＋ Product frame","pl":"＋ Ramka wyrobu","uk":"＋ Рамка виробу"},"＋ Текст":{"en":"＋ Text","pl":"＋ Tekst","uk":"＋ Текст"},"＋ Фурнитура":{"en":"＋ Hardware","pl":"＋ Okucia","uk":"＋ Фурнітура"},"＋ ряд":{"en":"＋ row","pl":"＋ wiersz","uk":"＋ ряд"},"＋ ячейка":{"en":"＋ cell","pl":"＋ komórka","uk":"＋ комірка"}});

styles:
/* полноэкранный редактор чертежей */
.drawingsHistory {
  width: min(520px, 90vw);
  max-height: 80vh;
  max-height: 80dvh; /* телефон: без строки адреса браузера */
  overflow: auto;
  color: #e9f1f4;
  background: #1b252c;
  border: 1px solid #6fe3d3;
  border-radius: 8px;
}
.drawingsHistory::backdrop {
  background: #0008;
}
#drawingsHistoryList button { display: block; width: 100%; margin: 4px 0; text-align: left; }
.drawingsApp {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  grid-template-columns: 170px 1fr 290px;
  grid-template-rows: auto 1fr;
  background: #1b252c;
  color: var(--text, #e9f1f4);
  font: 13px/1.35 system-ui;
}
.drawingsApp[hidden] {
  display: none;
}
.drawingsBar {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: #121a20;
  border-bottom: 1px solid #2c3a44;
}
.drawingsTitle {
  margin-right: 8px;
  font-size: 15px;
}
.drawingsSpacer {
  flex: 1;
}
.drawingsPrimary {
  background: #315e5d;
  border-color: var(--accent, #6fe3d3);
}
.drawingsSheets {
  overflow: auto;
  padding: 8px;
  border-right: 1px solid #2c3a44;
}
.drawingsSheetItem {
  display: block;
  width: 100%;
  margin-bottom: 8px;
  padding: 5px;
  border: 1px solid #34454f;
  border-radius: 6px;
  background: #22303a;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.drawingsSheetItem.on {
  border-color: var(--accent, #6fe3d3);
  background: #284048;
}
.drawingsSheetItem small {
  display: block;
  color: #9fb0b8;
}
.drawingsStage {
  position: relative;
  overflow: auto;
  background: #59656c;
}
.drawingsPaper {
  margin: 24px auto;
  width: max-content;
  box-shadow: 0 6px 24px #0008;
}
.drawingsPaper svg {
  display: block;
  background: #fff;
}
.drawingsZoom {
  position: sticky;
  left: 100%;
  bottom: 10px;
  float: right;
  display: flex;
  gap: 4px;
  margin: 0 10px 10px 0;
}
.drawingsProps {
  overflow: auto;
  padding: 10px;
  border-left: 1px solid #2c3a44;
}
.drawingsProps h4 {
  margin: 12px 0 6px;
  font-size: 13px;
  color: #b7c8d0;
}
.drawingsProps h4:first-child {
  margin-top: 0;
}
.drawingsField {
  display: grid;
  grid-template-columns: 96px 1fr;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}
.drawingsField span {
  color: #b7c8d0;
}
.drawingsField input,
.drawingsField select,
.drawingsField textarea {
  width: 100%;
  box-sizing: border-box;
}
.drawingsField textarea {
  min-height: 60px;
}
.drawingsProps .drawingsButtons {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.drawingsDanger {
  border-color: #b06a5e;
  color: #ffc4ba;
}
/* блоки на листе: рамка выбора и ручка размера рисуются в SVG */
.drawingsBlock {
  cursor: move;
}
.drawingsHandle {
  cursor: nwse-resize;
}
/* печать: только листы, каждый своим форматом (имя страницы — формат+ориентация) */
.drawingsPrintRoot {
  display: none;
}
@media print {
  body > *:not(.drawingsPrintRoot) {
    display: none !important;
  }
  .drawingsPrintRoot {
    display: block;
  }
  .drawingsPrintRoot svg {
    display: block;
    break-after: page;
  }
}
@media (max-width: 900px) {
  .drawingsApp {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr auto;
  }
  .drawingsSheets {
    display: flex;
    gap: 6px;
    border-right: 0;
    border-bottom: 1px solid #2c3a44;
  }
  .drawingsSheetItem {
    width: auto;
    margin: 0;
  }
  .drawingsProps {
    max-height: 38vh;
    border-left: 0;
    border-top: 1px solid #2c3a44;
  }
}
.drawingsHint {
  display: block;
  margin: 2px 0 8px;
  color: #9fb0b8;
}
/* шаблон рамки: ряд — ячейки (поле, доля ширины, ✕) */
.drawingsStampRow {
  margin: 6px 0;
  padding: 6px;
  border: 1px solid #34454f;
  border-radius: 6px;
}
.drawingsStampRow > small {
  display: block;
  margin-bottom: 4px;
  color: #9fb0b8;
}
.drawingsStampCell {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 4px;
}
.drawingsStampCell select {
  flex: 1;
  min-width: 110px;
}
.drawingsStampCell input {
  flex: 1;
  min-width: 70px;
}
.drawingsStampCell input.drawingsStampW {
  flex: none;
  width: 52px;
  min-width: 0;
}
/* список листов: «Параметры комплекта» первым, листы окрашены по виду */
.drawingsSetupItem {
  display: block;
  width: 100%;
  margin-bottom: 10px;
  padding: 7px 5px;
  border: 1px dashed #5d7380;
  border-radius: 6px;
  background: #1f2a31;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.drawingsSetupItem.on {
  border-style: solid;
  border-color: var(--accent, #6fe3d3);
  background: #284048;
}
.drawingsSheetItem {
  border-left-width: 4px;
}
.drawingsKind-title {
  border-left-color: #e0b84f;
}
.drawingsKind-sheet {
  border-left-color: #4fa3e0;
}
.drawingsKind-spec {
  border-left-color: #6fcf8a;
}
.drawingsKind-part {
  border-left-color: #c58ae0;
}
.drawingsSheetItem.drawingsDropAt {
  box-shadow: 0 -3px 0 var(--accent, #6fe3d3);
}
/* страница «Параметры комплекта» — вместо листа */
.drawingsOnSetup .drawingsZoom {
  display: none;
}
.drawingsOnSetup .drawingsPaper {
  width: auto;
  margin: 0;
  box-shadow: none;
}
.drawingsSetup {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 14px;
  padding: 16px;
  color: var(--text, #e9f1f4);
}
.drawingsSetup section {
  padding: 10px 12px;
  border: 1px solid #34454f;
  border-radius: 8px;
  background: #1f2a31;
}
.drawingsSetup h4 {
  margin: 0 0 8px;
  font-size: 13px;
  color: #b7c8d0;
}
.drawingsSetup .drawingsField {
  grid-template-columns: 120px 1fr;
}
.drawingsSetup .drawingsButtons {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.drawingsChecks {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 2px 8px;
  margin: 4px 0 8px;
}
.drawingsChecks .drawingsField {
  grid-column: 1 / -1;
}
/* шаблоны: подпись группы кнопок, подсветка раздела при переходе */
.drawingsGroup {
  margin-left: 10px;
  color: #9fb0b8;
}
.drawingsSetup section.drawingsFlash {
  border-color: var(--accent, #6fe3d3);
  box-shadow: 0 0 0 2px var(--accent, #6fe3d3);
}
.drawingsColRow {
  align-items: center;
}
.drawingsColRow input[type='checkbox'] {
  flex: none;
  min-width: 0;
}
.drawingsProject {
  cursor: crosshair;
}
/* выноски вида в свойствах */
.drawingsNoteRow > small {
  cursor: pointer;
  color: var(--text, #e9f1f4);
}
.drawingsNoteRow.on {
  border-color: var(--accent, #6fe3d3);
}
.drawingsNoteRow textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 48px;
  margin-bottom: 6px;
}
.drawingsNoteLabel {
  cursor: grab;
}
.drawingsSearch {
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 8px;
}
.drawingsBack {
  display: block;
  width: 100%;
  margin-bottom: 8px;
  text-align: left;
}
/* окно исключений из спецификаций */
.drawingsDialog {
  width: min(900px, 92vw);
  max-height: 86vh;
  overflow: auto;
  padding: 16px;
  border: 1px solid #34454f;
  border-radius: 10px;
  background: #1b252c;
  color: var(--text, #e9f1f4);
  font: 13px/1.35 system-ui;
}
.drawingsDialog::backdrop {
  background: #0008;
}
.drawingsDialog h3 {
  margin: 0 0 6px;
}
.drawingsExcludeCols {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 14px;
  margin: 8px 0 12px;
}
.drawingsExcludeCols label {
  display: flex;
  gap: 6px;
  align-items: flex-start;
  padding: 2px 0;
}
.drawingsDialog {
  padding-top: 0;
}
.drawingsDialogHead {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 0 8px;
  background: #1b252c;
  border-bottom: 1px solid #34454f;
}
.drawingsDialogHead button {
  flex: none;
}
.drawingsExcludeRow {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 6px;
  align-items: center;
  padding: 2px 0;
  border-bottom: 1px solid #26343d;
}
.drawingsToggle {
  min-width: 46px;
  padding: 2px 6px;
  border: 1px solid #4a5b66;
  border-radius: 5px;
  background: #22303a;
  color: #7f909a;
  font: inherit;
  text-decoration: line-through;
  cursor: pointer;
}
.drawingsToggle.on {
  border-color: var(--accent, #6fe3d3);
  background: #284048;
  color: var(--text, #e9f1f4);
  text-decoration: none;
}
/* лист «Общий вид» — свой цвет в списке */
.drawingsKind-overview {
  border-left-color: #e06fa8;
}
/* структура модели в свойствах листа общего вида */
/* выбранный размер (Delete удаляет) */
.drawingsDimSel line:not(.drawingsAutoDimHit):not(.drawingsMeasureHit),
.drawingsDimSel path {
  stroke: #1e88e5;
  fill: #1e88e5;
}
.drawingsDimSel text {
  fill: #1e88e5;
}
/* размер между деталями, чьих деталей нет на виде: стоит по последним точкам (только в
   редакторе, на печать — как обычный) */
#drawingsPaper .drawingsDimLost line:not(.drawingsMeasureHit),
#drawingsPaper .drawingsDimLost path {
  stroke: #ef6c00;
  fill: #ef6c00;
  stroke-dasharray: 1 0.6;
}
#drawingsPaper .drawingsDimLost text {
  fill: #ef6c00;
}
.drawingsDimTextInput {
  width: 70px;
}
.drawingsTree {
  max-height: 46vh;
  overflow: auto;
  padding: 4px 0;
  border: 1px solid #34454f;
  border-radius: 6px;
}
.drawingsTree details {
  margin-left: 10px;
}
.drawingsTree > details {
  margin-left: 2px;
}
.drawingsTree summary {
  cursor: pointer;
}
.drawingsTree label {
  display: inline-flex;
  gap: 4px;
  align-items: center;
}
/* «СЕ» у узла структуры: свой узел — сборочной единицей, рядом обозначение */
.drawingsUnitToggle {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  margin-left: 6px;
}
.drawingsUnitToggle button {
  padding: 0 6px;
  font-size: 11px;
  line-height: 18px;
}
.drawingsUnitToggle button.drawingsOn {
  background: #2e7d6b;
  color: #fff;
}
.drawingsUnitCode {
  width: 70px;
  font-size: 11px;
}
/* длинное название узла переносится рядом со стрелкой, а не под неё */
.drawingsTree summary label {
  display: inline;
}
.drawingsTree .drawingsTreeAll {
  margin-left: 4px;
  padding: 0 4px;
  font-size: 11px;
  line-height: 16px;
}
.drawingsTree .drawingsTreeLeaf {
  display: flex;
  margin-left: 24px;
}
.drawingsMoveRow {
  display: flex;
  gap: 6px;
  align-items: center;
}
/* ключ к чертежам — строка в «☰ → Ещё» */
.drawingsKeyTools {
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.drawingsKeyTools input {
  width: 150px;
  min-width: 0;
}
.drawingsKeyTools [hidden],
#drawingsOpen[hidden] {
  display: none !important;
}

/* полки выносок позиций и размерные линии размеров по точкам тянутся мышью */
.drawingsCalloutLabel,
.drawingsMeasureHit {
  cursor: move;
}
/* «На лист…» (DRAW-008): меню листов — в общем слое (portalToolMenu), вкладка листа,
   на которую тянут блок, — подсвечена целиком */
.drawingsProps .drawingsMoveMenu > summary {
  display: inline-block;
  padding: 7px 12px;
  font: inherit;
  color: inherit;
  border: 1px solid #415563;
  border-radius: 7px;
  background: #21313e;
  cursor: pointer;
  list-style: none;
}
.drawingsProps .drawingsMoveMenu[open] > summary {
  background: #304654;
  border-color: var(--accent, #6fe3d3);
}
.drawingsMoveMenu > summary::-webkit-details-marker {
  display: none;
}
.drawingsMoveList button {
  display: block;
  width: 100%;
  margin: 3px 0;
  text-align: left;
}
.drawingsMoveList button.on {
  border-color: var(--accent, #6fe3d3);
  opacity: 0.6;
}
.drawingsSheetItem.drawingsDropBlock {
  box-shadow: none;
  outline: 2px solid var(--accent, #6fe3d3);
  outline-offset: -2px;
  background: #2a4a50;
}
